/** P01.T335 — A1: adresa serverului (doar https, S7), utilizatorul, parola; «Intră» ⇒ E1a ⇒ A2. */
class IntrareActivity : AppCompatActivity() {

    private lateinit var b: ActivityIntrareBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        b = ActivityIntrareBinding.inflate(layoutInflater)
        setContentView(b.root)
        val app = application as AplicatieEva
        if (savedInstanceState == null) {
            app.adresaSalvata()?.let { b.adresa.setText(it) }
        }
        // Î-1 (06b): A1 = fără sesiune valabilă ⇒ jetonul rămas (eșec E3/E4, proces oprit) se șterge (C-8)
        app.depozit.sterge()
        intent.getIntExtra(EXTRA_MESAJ, 0).takeIf { it != 0 }?.let { arata(getString(it)) }
        b.intra.setOnClickListener { intra(app) }
    }

    private fun intra(app: AplicatieEva) {
        val adresa = AdresaServer.valideaza(b.adresa.text.toString())
        if (adresa !is Rezultat.Ok) {
            arata(Mesaje.text(this, (adresa as Rezultat.Esec).eroare))
            return
        }
        val utilizator = b.utilizator.text.toString()
        val parola = b.parola.text.toString()
        b.parola.text?.clear()
        val sesiune = app.deschide(adresa.valoare)
        ocupat(true)
        lifecycleScope.launch {
            val r = withContext(Dispatchers.IO) { sesiune.intra(utilizator, parola) }
            ocupat(false)
            when (r) {
                is Rezultat.Ok -> {
                    app.utilizator = utilizator
                    app.provizoriu = r.valoare
                    startActivity(Intent(this@IntrareActivity, FirmaRolActivity::class.java))
                }
                is Rezultat.Esec -> arata(Mesaje.text(this@IntrareActivity, r.eroare))
            }
        }
    }

    private fun ocupat(da: Boolean) {
        b.intra.isEnabled = !da
        b.progres.visibility = if (da) View.VISIBLE else View.GONE
    }

    private fun arata(text: String) {
        b.mesaj.text = text
        b.mesaj.visibility = View.VISIBLE
    }

    companion object {
        const val EXTRA_MESAJ = "ro.eva.mobil.MESAJ"

        /** Întoarcerea la A1 cu mesajul erorii (jeton șters, 401 repetat, 403). */
        fun inapoi(context: Context, @StringRes mesaj: Int?): Intent =
            Intent(context, IntrareActivity::class.java)
                .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TASK or Intent.FLAG_ACTIVITY_NEW_TASK)
                .apply { if (mesaj != null) putExtra(EXTRA_MESAJ, mesaj) }
    }
}
