@RunWith(AndroidJUnit4::class)
class CameraTest {

    @get:Rule val permisiune: GrantPermissionRule = GrantPermissionRule.grant(Manifest.permission.CAMERA)

    @Test fun analizorulPrimesteCadre() {
        ActivityScenario.launch(ScanareProbaActivity::class.java).use { sc ->
            Banc.asteapta(60_000) {
                var n = 0
                sc.onActivity { n = it.vizor.analizor?.cadre ?: 0 }
                assertTrue("cadre primite: $n", n >= 1)
            }
            Banc.captura("camera_cadre")
        }
    }

    @Test fun cameraRefuzataHidFunctional() {
        val refuzata = object : ContextWrapper(Banc.instr.targetContext) {
            override fun checkPermission(permission: String, pid: Int, uid: Int): Int =
                if (permission == Manifest.permission.CAMERA) PackageManager.PERMISSION_DENIED
                else super.checkPermission(permission, pid, uid)
            override fun checkSelfPermission(permission: String): Int =
                if (permission == Manifest.permission.CAMERA) PackageManager.PERMISSION_DENIED
                else super.checkSelfPermission(permission)
        }
        val coduri = ArrayList<String>()
        var mesaj = 0
        ActivityScenario.launch(ScanareProbaActivity::class.java).use { sc ->
            sc.onActivity { act ->
                val v = VizorScanare(refuzata, { coduri.add(it) }, {}, { mesaj++ })
        Banc.curata()
        s = Banc.server()
    }

    @After fun inchide() = s.shutdown()

